head.script:
scwin.test = function(id) {
    var tabOpt = {
        label: id,
        closable: true,
        openAction: "select"
    };
    var contOpt = {
        frameMode: "iframe",
        src: "tabControl_spaInitCount_WPF-1854_(WSQ-2955)_sub.xml"
    };
    var newTabID = tabControl1.addTab(id, tabOpt, contOpt);
}
scwin.tabControl1_ontabclick = function(tabID, idx) {
    console.log("idx ====> " + idx);
};
scwin.trigger1_onclick = function(e) {
    scwin.test("test1");
};
scwin.trigger2_onclick = function(e) {
    scwin.test("test2");
};
scwin.isEleInEle = function(el1Id, el2Id) {
    var el = WebSquare.wUnit.getDomById(el1Id).firstElementChild;
    return el.id == $p.id+el2Id;
}
scwin.isEleInEle1 = function(el1Id, el2Id) {
    var el = WebSquare.wUnit.getDomById(el1Id).lastElementChild;
    return el.id == $p.id+el2Id;
}
scwin.isEleClosed = function(id) {
    var el = WebSquare.wUnit.getDomById(id);
    return el.style.display == "none";
}
scwin.hasErrlog = function() {
    return WebSquare.logger.getErrorLog();
}
scwin.checktype = function() {
    return typeof tabControl1_contents_test2 === 'undefined';
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 'test1 addTab'버튼과 'test1 addTab'버튼을 클릭한다.
    //1. Run the sample file and click the 'test1 addTab' button and the 'test1 addTab' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    // verify step 1. iframe으로 addTab이 생성되어진다.
    //1. addTab is created in iframe.
    WebSquare.wUnit.addCommand("assert", "scwin.isEleInEle('tabControl1_container', 'tabControl1_contents_test1')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.isEleInEle1('tabControl1_container', 'tabControl1_contents_test2')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. 생성된 탭을 닫는다.
    //2. Close the created tab.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabControl1_tab_test1_close').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabControl1_tab_test2_close').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 2. iframe으로 생성된 addTab이 closed되어진다.
    //2. The addTab generated by the iframe is closed.
    WebSquare.wUnit.addCommand("assert", "scwin.isEleClosed('tabControl1_contents_test1')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checktype()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 3. 1번과 2번을 반복하여 수행하고 로그를 확인한다.
    //3. Repeat steps 1 and 2 and check the log.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabControl1_tab_test2_close').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 3. 정상적으로 수행되고 로그도 정상으로 보여진다.(이전에는 로그오류 발생)
    //3. It is normally executed and the log is displayed normally.(Previously a log error occurred)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('tabControl1_tabhost').childNodes.length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.hasErrlog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function unitTest
    //Created By: Sang.do
    //Created By: 19-Jan-2018
    //end unitTest
}
